from datetime import datetime
from pathlib import Path
import random
import sqlite3

import pandas as pd

import config
import friends
import models


SCHEMA = """
CREATE TABLE IF NOT EXISTS directions (
    id          INTEGER PRIMARY KEY,
    key         TEXT NOT NULL UNIQUE,          -- 'sports' | 'leisure' | 'career'
    name        TEXT NOT NULL,
    sort_order  INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS bundles (
    id            INTEGER PRIMARY KEY,
    key           TEXT NOT NULL UNIQUE,        -- e.g. 'sports_racket'
    direction_id  INTEGER NOT NULL REFERENCES directions(id),
    name          TEXT NOT NULL,
    is_other      INTEGER NOT NULL DEFAULT 0,
    sort_order    INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS clubs (
    id             INTEGER PRIMARY KEY,
    name           TEXT NOT NULL UNIQUE,
    club_category  TEXT,                       -- UniClubs category, e.g. 'Business'
    url            TEXT
);

CREATE TABLE IF NOT EXISTS series (
    id                INTEGER PRIMARY KEY,
    source            TEXT NOT NULL CHECK (source IN ('unisport', 'uniclubs', 'city')),
    external_id       TEXT NOT NULL,
    title             TEXT NOT NULL,
    description       TEXT NOT NULL DEFAULT '',
    organizer         TEXT NOT NULL DEFAULT '',
    club_id           INTEGER REFERENCES clubs(id),
    bundle_id         INTEGER NOT NULL REFERENCES bundles(id),
    event_type        TEXT NOT NULL DEFAULT '',
    sport             TEXT NOT NULL DEFAULT '',       -- Unisport only
    level             TEXT NOT NULL DEFAULT '',       -- Unisport only
    location          TEXT NOT NULL DEFAULT '',
    location_type     TEXT NOT NULL
                      CHECK (location_type IN ('st_gallen', 'online', 'elsewhere', 'tba')),
    source_url        TEXT NOT NULL DEFAULT '',
    registration_url  TEXT NOT NULL DEFAULT '',
    price_rappen      INTEGER,                        -- NULL = unknown, 0 = free
    members_only      INTEGER NOT NULL DEFAULT 0,
    is_recurring      INTEGER NOT NULL DEFAULT 0,
    is_placeholder    INTEGER NOT NULL DEFAULT 0,     -- 1 = synthetic placeholder data
    UNIQUE (source, external_id)
);

CREATE TABLE IF NOT EXISTS events (
    id                INTEGER PRIMARY KEY,
    series_id         INTEGER NOT NULL REFERENCES series(id),
    start_time        TEXT NOT NULL,                  -- 'YYYY-MM-DD HH:MM:SS', Europe/Zurich
    end_time          TEXT NOT NULL,
    end_is_estimated  INTEGER NOT NULL DEFAULT 0,
    status            TEXT NOT NULL DEFAULT 'open'
                      CHECK (status IN
                             ('open', 'apply', 'members_only', 'ongoing', 'full', 'closed')),
    UNIQUE (series_id, start_time)
);

CREATE TABLE IF NOT EXISTS users (
    id              INTEGER PRIMARY KEY,
    display_name    TEXT NOT NULL,
    friend_code     TEXT NOT NULL UNIQUE,
    is_synthetic    INTEGER NOT NULL DEFAULT 1,
    sharing_opt_in  INTEGER NOT NULL DEFAULT 0,
    created_at      TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS user_directions (
    id            INTEGER PRIMARY KEY,
    user_id       INTEGER NOT NULL REFERENCES users(id),
    direction_id  INTEGER NOT NULL REFERENCES directions(id),
    UNIQUE (user_id, direction_id)
);

-- One table for three kinds of favorites. target_id points to series.id, clubs.id or
-- bundles.id depending on kind, so SQLite cannot enforce it as a foreign key:
-- add_favorite() checks that the target exists before inserting.  [DEFAULT D-21]
CREATE TABLE IF NOT EXISTS favorites (
    id          INTEGER PRIMARY KEY,
    user_id     INTEGER NOT NULL REFERENCES users(id),
    kind        TEXT NOT NULL CHECK (kind IN ('series', 'club', 'bundle')),
    target_id   INTEGER NOT NULL,
    created_at  TEXT NOT NULL,
    UNIQUE (user_id, kind, target_id)
);

CREATE TABLE IF NOT EXISTS interactions (
    id            INTEGER PRIMARY KEY,
    user_id       INTEGER NOT NULL REFERENCES users(id),
    event_id      INTEGER NOT NULL REFERENCES events(id),
    status        TEXT NOT NULL
                  CHECK (status IN ('confirmed', 'cancelled', 'attended', 'not_attended')),
    rating        INTEGER CHECK (rating BETWEEN 1 AND 5),
    confirmed_at  TEXT NOT NULL,
    answered_at   TEXT,
    is_demo       INTEGER NOT NULL DEFAULT 0,   -- 1 = local user's demo history [DEFAULT D-25]
    UNIQUE (user_id, event_id),
    CHECK (rating IS NULL OR status = 'attended')
);

CREATE TABLE IF NOT EXISTS friendships (
    id          INTEGER PRIMARY KEY,
    user_id     INTEGER NOT NULL REFERENCES users(id),
    friend_id   INTEGER NOT NULL REFERENCES users(id),
    created_at  TEXT NOT NULL,
    UNIQUE (user_id, friend_id),
    CHECK (user_id <> friend_id)
);

CREATE TABLE IF NOT EXISTS invitations (
    id            INTEGER PRIMARY KEY,
    sender_id     INTEGER NOT NULL REFERENCES users(id),
    recipient_id  INTEGER NOT NULL REFERENCES users(id),
    event_id      INTEGER NOT NULL REFERENCES events(id),
    status        TEXT NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'accepted', 'declined')),
    is_simulated  INTEGER NOT NULL DEFAULT 0,
    created_at    TEXT NOT NULL,
    answered_at   TEXT,
    UNIQUE (sender_id, recipient_id, event_id)
);

CREATE TABLE IF NOT EXISTS app_settings (
    id     INTEGER PRIMARY KEY,
    key    TEXT NOT NULL UNIQUE,
    value  TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS import_log (
    id           INTEGER PRIMARY KEY,
    source       TEXT NOT NULL,
    started_at   TEXT NOT NULL,
    origin       TEXT NOT NULL CHECK (origin IN ('live', 'snapshot', 'placeholder', 'excel')),
    n_series     INTEGER NOT NULL DEFAULT 0,
    n_events     INTEGER NOT NULL DEFAULT 0,
    outcome      TEXT NOT NULL CHECK (outcome IN ('ok', 'failed', 'rejected')),
    message      TEXT NOT NULL DEFAULT ''
);
"""


EVENTS_IN_RANGE_SQL = '''
SELECT e.id, e.series_id, e.start_time, e.end_time, e.end_is_estimated, e.status,
        s.source, s.title, s.description, s.organizer, s.event_type, s.sport, s.level,
        s.location, s.location_type, s.source_url, s.registration_url, s.price_rappen,
        s.members_only, s.is_recurring, s.club_id, c.name AS club_name, c.club_category,
        b.key AS bundle_key, b.name AS bundle_name, d.key AS direction_key
 FROM events e JOIN series s ON s.id=e.series_id
 JOIN bundles b ON b.id=s.bundle_id JOIN directions d ON d.id=b.direction_id
 LEFT JOIN clubs c ON c.id=s.club_id
 WHERE e.start_time>=? AND e.start_time<? ORDER BY e.start_time
'''

EVENT_BY_ID_SQL = '''
SELECT e.id, e.series_id, e.start_time, e.end_time, e.end_is_estimated, e.status,
        s.source, s.title, s.description, s.organizer, s.event_type, s.sport, s.level,
        s.location, s.location_type, s.source_url, s.registration_url, s.price_rappen,
        s.members_only, s.is_recurring, s.club_id, c.name AS club_name, c.club_category,
        b.key AS bundle_key, b.name AS bundle_name, d.key AS direction_key
 FROM events e JOIN series s ON s.id=e.series_id
 JOIN bundles b ON b.id=s.bundle_id JOIN directions d ON d.id=b.direction_id
 LEFT JOIN clubs c ON c.id=s.club_id
 WHERE e.id=?
'''

CONFIRMED_EVENTS_SQL = '''
SELECT e.id, e.series_id, e.start_time, e.end_time, e.end_is_estimated, e.status,
        s.source, s.title, s.description, s.organizer, s.event_type, s.sport, s.level,
        s.location, s.location_type, s.source_url, s.registration_url, s.price_rappen,
        s.members_only, s.is_recurring, s.club_id, c.name AS club_name, c.club_category,
        b.key AS bundle_key, b.name AS bundle_name, d.key AS direction_key
 FROM events e JOIN series s ON s.id=e.series_id
 JOIN bundles b ON b.id=s.bundle_id JOIN directions d ON d.id=b.direction_id
 LEFT JOIN clubs c ON c.id=s.club_id
 JOIN interactions i ON i.event_id=e.id
 WHERE i.user_id=? AND i.status IN ('confirmed','attended','not_attended')
 AND e.start_time<? AND e.end_time>?
 ORDER BY e.start_time
'''


def get_connection(db_file=config.DB_FILE, uri=False):
    """Open SQLite with foreign keys; URI mode lets tests share an in-memory request database."""
    if str(db_file) != ':memory:' and not uri:
        Path(db_file).parent.mkdir(parents=True, exist_ok=True)
    # Streamlit may reuse the local connection on another rerun thread (SPEC section 6).
    connection = sqlite3.connect(db_file, timeout=config.DB_TIMEOUT_SECONDS,
                                 check_same_thread=False, uri=uri)
    connection.row_factory = sqlite3.Row
    # Course: A07 – foreign-key enforcement is enabled per connection.
    connection.execute('PRAGMA foreign_keys = 1')
    return connection


def init_db(connection):
    """Create the complete specification schema without disturbing existing rows."""
    with connection:
        for statement in SCHEMA.split(';'):
            if statement.strip():
                connection.execute(statement)


def to_db_text(dt):
    """Serialize a naive local datetime using the shared format."""
    if not isinstance(dt, datetime) or dt.tzinfo is not None:
        raise ValueError('Database time must be a naive local datetime.')
    return dt.strftime(config.DB_TIME_FORMAT)


def from_db_text(text):
    """Parse the shared SQLite timestamp representation."""
    return datetime.strptime(text, config.DB_TIME_FORMAT)


def get_setting(connection, key, default=None):
    """Read one non-secret setting with a default for an absent key."""
    row = connection.execute('SELECT value FROM app_settings WHERE key=?', (key,)).fetchone()
    return row['value'] if row is not None else default


def set_setting(connection, key, value):
    """Upsert one non-secret setting using a bound parameter tuple."""
    with connection:
        connection.execute('''INSERT INTO app_settings (key,value) VALUES (?,?)
            ON CONFLICT(key) DO UPDATE SET value=excluded.value''', (key, str(value)))


def seed_taxonomy(connection, taxonomy):
    """Upsert taxonomy metadata while preserving referenced IDs."""
    with connection:
        for row in taxonomy['directions']:
            connection.execute('''INSERT INTO directions (key,name,sort_order) VALUES (?,?,?)
                ON CONFLICT(key) DO UPDATE SET name=excluded.name, sort_order=excluded.sort_order
            ''', (row['key'], row['name'], row['sort_order']))
        for row in taxonomy['bundles']:
            direction = connection.execute('SELECT id FROM directions WHERE key=?',
                                           (row['direction'],)).fetchone()
            connection.execute('''INSERT INTO bundles (key,direction_id,name,is_other,sort_order)
                VALUES (?,?,?,?,?) ON CONFLICT(key) DO UPDATE SET name=excluded.name,
                is_other=excluded.is_other, sort_order=excluded.sort_order''',
                (row['key'], direction['id'], row['name'], int(row['is_other']), row['sort_order']))
    set_setting(connection, 'taxonomy_version', taxonomy['_meta']['version'])


def _upsert_club(connection, name, club_category='', url=''):
    """Upsert one club inside the caller's transaction."""
    if not name:
        return None
    connection.execute('''INSERT INTO clubs (name,club_category,url) VALUES (?,?,?)
        ON CONFLICT(name) DO UPDATE SET club_category=excluded.club_category,url=excluded.url
    ''', (name, club_category, url))
    return connection.execute('SELECT id FROM clubs WHERE name=?', (name,)).fetchone()['id']


def upsert_club(connection, name, club_category='', url=''):
    """Store a club and return its stable ID."""
    with connection:
        return _upsert_club(connection, name, club_category, url)


def _upsert_series(connection, record, bundle_id, club_id):
    """Upsert an activity's canonical fields inside the caller's transaction."""
    values = [record.get(field, '') for field in config.SERIES_RECORD_FIELDS]
    values.extend([club_id, bundle_id, models.price_to_rappen(record.get('price')),
                   int(record.get('members_only', False)), int(record.get('is_recurring', False)),
                   int(record.get('is_placeholder', False))])
    connection.execute('''INSERT INTO series
        (source,external_id,title,description,organizer,event_type,sport,level,location,
         location_type,source_url,registration_url,club_id,bundle_id,price_rappen,
         members_only,is_recurring,is_placeholder) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        ON CONFLICT(source,external_id) DO UPDATE SET title=excluded.title,
        description=excluded.description,organizer=excluded.organizer,
        event_type=excluded.event_type,
        sport=excluded.sport,level=excluded.level,location=excluded.location,
        location_type=excluded.location_type,source_url=excluded.source_url,
        registration_url=excluded.registration_url,club_id=excluded.club_id,
        bundle_id=excluded.bundle_id,
        price_rappen=excluded.price_rappen,members_only=excluded.members_only,
        is_recurring=excluded.is_recurring,is_placeholder=excluded.is_placeholder
    ''', tuple(values))
    return connection.execute('SELECT id FROM series WHERE source=? AND external_id=?',
                              (record['source'], record['external_id'])).fetchone()['id']


def upsert_series(connection, record, bundle_id, club_id=None):
    """Store one activity by its source/external-ID natural key."""
    with connection:
        return _upsert_series(connection, record, bundle_id, club_id)


def _upsert_event(connection, series_id, start, end, end_is_estimated, status):
    """Upsert one dated occurrence without replacing its identity."""
    connection.execute('''INSERT INTO events
        (series_id,start_time,end_time,end_is_estimated,status) VALUES (?,?,?,?,?)
        ON CONFLICT(series_id,start_time) DO UPDATE SET end_time=excluded.end_time,
        end_is_estimated=excluded.end_is_estimated,status=excluded.status
    ''', (series_id, to_db_text(start), to_db_text(end), int(end_is_estimated), status))
    return connection.execute('SELECT id FROM events WHERE series_id=? AND start_time=?',
                              (series_id, to_db_text(start))).fetchone()['id']


def upsert_event(connection, series_id, start, end, end_is_estimated=False, status='open'):
    """Store one valid occurrence with transactional foreign-key enforcement."""
    if end <= start or status not in config.EVENT_STATUSES:
        raise ValueError('Invalid event interval or status.')
    with connection:
        return _upsert_event(connection, series_id, start, end, end_is_estimated, status)


def apply_source_records(connection, records, source, reconcile=False, now=None):
    """Commit a validated batch atomically and return distinct series/occurrence counts."""
    series_ids, event_ids = set(), set()
    with connection:
        for record in records:
            bundle = connection.execute('SELECT id FROM bundles WHERE key=?',
                                        (record['bundle_key'],)).fetchone()
            if bundle is None:
                raise ValueError('Unknown bundle in source batch.')
            club_id = _upsert_club(connection, record.get('club_name', ''),
                                   record.get('club_category', ''))
            series_id = _upsert_series(connection, record, bundle['id'], club_id)
            event_id = _upsert_event(connection, series_id, record['start'], record['end'],
                                     record['end_is_estimated'], record['status'])
            series_ids.add(series_id)
            event_ids.add(event_id)
        if reconcile:
            _delete_missing_future(connection, source, event_ids, config.local_now(now))
    return len(series_ids), len(event_ids)


def _delete_missing_future(connection, source, retained_ids, now):
    """Delete absent future events only when no interaction or invitation refers to them."""
    rows = connection.execute('''SELECT e.id FROM events e JOIN series s ON s.id=e.series_id
        WHERE s.source=? AND e.start_time>?
        AND NOT EXISTS (SELECT 1 FROM interactions WHERE event_id=e.id)
        AND NOT EXISTS (SELECT 1 FROM invitations WHERE event_id=e.id)
    ''', (source, to_db_text(now))).fetchall()
    for row in rows:
        if row['id'] not in retained_ids:
            connection.execute('DELETE FROM events WHERE id=?', (row['id'],))


def get_events_df(connection, start, end):
    """Return joined occurrences in [start,end), preserving nullable integer Rappen exactly."""
    # An object frame prevents nullable money/IDs from silently becoming imprecise floats.
    rows = get_event_records(connection, start, end)
    return pd.DataFrame(rows, columns=config.EVENT_RECORD_FIELDS, dtype=object).set_index('id')


def get_event_records(connection, start, end):
    """Return the shared event row format with SQLite integers and None intact for JSON."""
    rows = connection.execute(EVENTS_IN_RANGE_SQL,
                               (to_db_text(start), to_db_text(end))).fetchall()
    return [dict(row) for row in rows]


def get_event_row(connection, event_id):
    """Return one joined dictionary, or None when the event does not exist."""
    row = connection.execute(EVENT_BY_ID_SQL, (event_id,)).fetchone()
    return dict(row) if row is not None else None


def get_event_date_range(connection):
    """Return the earliest/latest occurrence dates, or (None, None)."""
    row = connection.execute('SELECT MIN(start_time),MAX(start_time) FROM events').fetchone()
    if row[0] is None:
        return None, None
    return from_db_text(row[0]).date(), from_db_text(row[1]).date()


def get_categories_df(connection):
    """Return bundles joined to their directions in taxonomy order."""
    return pd.read_sql('''SELECT b.id,b.key AS bundle_key,b.name AS bundle_name,
        d.key AS direction_key,d.name AS direction_name FROM bundles b
        JOIN directions d ON d.id=b.direction_id ORDER BY d.sort_order,b.sort_order
    ''', connection, index_col=['id'])


def get_source_counts_df(connection):
    """Return stored source totals for the data-status panel."""
    return pd.read_sql('''SELECT MIN(s.id) AS id,s.source,COUNT(DISTINCT s.id) AS series,
        COUNT(e.id) AS occurrences,
        COUNT(DISTINCT CASE WHEN s.is_placeholder=1 THEN s.id END) AS placeholder_series
        FROM series s LEFT JOIN events e ON e.series_id=s.id
        GROUP BY s.source''', connection, index_col=['id'])


def delete_past_unconfirmed_events(connection, now=None):
    """Delete ended occurrences only when no history or invitation refers to them."""
    with connection:
        cursor = connection.execute('''DELETE FROM events WHERE end_time<?
            AND NOT EXISTS (SELECT 1 FROM interactions WHERE event_id=events.id)
            AND NOT EXISTS (SELECT 1 FROM invitations WHERE event_id=events.id)
        ''', (to_db_text(config.local_now(now)),))
    return cursor.rowcount


def log_import(connection, source, origin, n_series=0, n_events=0,
               outcome='ok', message='', now=None):
    """Append one sanitized report for one complete source import run."""
    with connection:
        connection.execute('''INSERT INTO import_log
            (source,started_at,origin,n_series,n_events,outcome,message) VALUES (?,?,?,?,?,?,?)
        ''', (source, to_db_text(config.local_now(now)), origin,
              n_series, n_events, outcome, message))


def get_import_log_df(connection):
    """Return source-run reports, newest first."""
    return pd.read_sql('SELECT * FROM import_log ORDER BY id DESC', connection, index_col=['id'])


def get_calendar_confirmations(connection, start, end):
    """Read current-user plans and feedback overlapping the week, excluding cancellations."""
    user_id = get_setting(connection, 'current_user_id')
    return pd.read_sql(CONFIRMED_EVENTS_SQL, connection, index_col=['id'],
                       params=(user_id, to_db_text(end), to_db_text(start)))


def get_known_event_ids(connection):
    """Recognize stored occurrences even after cancellation; unknown external IDs stay busy."""
    rows = connection.execute('SELECT id FROM events').fetchall()
    return {row['id'] for row in rows}


def validate_profile(display_name, direction_keys):
    """Validate and normalize onboarding/profile input before any database write.

    :param display_name: name containing 2–20 visible characters
    :param direction_keys: at least one known focus direction
    :return: validated temporary UserProfile
    """
    profile = models.UserProfile(None, display_name, '', direction_keys)
    if not profile.directions:
        raise ValueError('Choose at least one focus direction.')
    return profile


def _require_user(connection, user_id):
    """Return an existing user row or reject an unknown profile."""
    row = connection.execute('SELECT * FROM users WHERE id=?', (user_id,)).fetchone()
    if row is None:
        raise ValueError('User profile was not found.')
    return row


def user_exists(connection, user_id):
    """Check a profile reference without exposing its private fields through the API."""
    return connection.execute('SELECT id FROM users WHERE id=?', (user_id,)).fetchone() is not None


def _create_user(connection, display_name, now, is_synthetic, sharing_opt_in,
                 friend_code=None, rng=None):
    """Insert a validated profile inside the caller's transaction."""
    existing = connection.execute('SELECT friend_code FROM users').fetchall()
    codes = {row['friend_code'] for row in existing}
    rng = rng or random.Random(config.RANDOM_SEED)
    code = friend_code or friends.generate_friend_code(codes, rng)
    if code in codes or len(code) != config.FRIEND_CODE_LENGTH or not code.isalnum():
        raise ValueError('Friend code must be unique and contain six letters or digits.')
    cursor = connection.execute('''INSERT INTO users
        (display_name,friend_code,is_synthetic,sharing_opt_in,created_at) VALUES (?,?,?,?,?)
        ''', (display_name, code, int(is_synthetic), int(sharing_opt_in), to_db_text(now)))
    return cursor.lastrowid


def create_user(connection, display_name, is_synthetic=False, sharing_opt_in=False, now=None,
                friend_code=None, rng=None):
    """Create a user with a generated friend code and return the new ID.

    :param connection: open SQLite connection
    :param display_name: validated visible name
    :param is_synthetic: mark a generated rather than local user
    :param sharing_opt_in: explicit permission to share plans, false by default
    :param now: injected local creation time
    :param friend_code: fixed showcase code, or None for a generated code
    :param rng: private seeded generator used by synthetic data
    :return: new user ID
    """
    name = models.UserProfile(None, display_name, '', []).display_name
    with connection:
        return _create_user(connection, name, config.local_now(now),
                            is_synthetic, sharing_opt_in, friend_code, rng)


def get_current_user_id(connection):
    """Return the stored local profile's ID, or None before onboarding."""
    value = get_setting(connection, 'current_user_id')
    if value is None:
        return None
    try:
        user_id = int(value)
    except ValueError as error:
        raise ValueError('Stored user profile is invalid.') from error
    _require_user(connection, user_id)
    return user_id


def _set_user_directions(connection, user_id, direction_keys):
    """Replace focus choices inside the caller's transaction after validation."""
    connection.execute('DELETE FROM user_directions WHERE user_id=?', (user_id,))
    for key in sorted(direction_keys):
        connection.execute('''INSERT INTO user_directions (user_id,direction_id)
            SELECT ?,id FROM directions WHERE key=?''', (user_id, key))


def set_user_directions(connection, user_id, direction_keys):
    """Persist a nonempty set of known focus directions for an existing user."""
    user = _require_user(connection, user_id)
    profile = validate_profile(user['display_name'], direction_keys)
    with connection:
        _set_user_directions(connection, user_id, profile.directions)


def update_user_profile(connection, user_id, display_name, direction_keys):
    """Save name and focus atomically, preserving favorites, history and sharing settings."""
    _require_user(connection, user_id)
    profile = validate_profile(display_name, direction_keys)
    with connection:
        connection.execute('UPDATE users SET display_name=? WHERE id=?',
                           (profile.display_name, user_id))
        _set_user_directions(connection, user_id, profile.directions)


def complete_onboarding(connection, display_name, direction_keys, calendar_mode, now=None,
                         load_demo_history=False):
    """Create the local profile and all non-secret onboarding settings atomically.

    :param connection: open SQLite connection
    :param display_name: user's chosen name
    :param direction_keys: nonempty focus selection
    :param calendar_mode: validated demo, link or upload mode; never a secret URL
    :param now: injected local creation time
    :param load_demo_history: persist the optional demo choice so startup can finish it safely
    :return: newly created local user ID
    """
    profile = validate_profile(display_name, direction_keys)
    if calendar_mode not in config.CALENDAR_MODES:
        raise ValueError('Choose a supported calendar source.')
    if get_current_user_id(connection) is not None:
        raise ValueError('A local profile already exists.')
    with connection:
        user_id = _create_user(connection, profile.display_name,
                               config.local_now(now), False, False)
        _set_user_directions(connection, user_id, profile.directions)
        for key, value in (('current_user_id', str(user_id)), ('calendar_mode', calendar_mode),
                           ('onboarding_done', '1'),
                           ('demo_history_requested', str(int(load_demo_history)))):
            connection.execute('''INSERT INTO app_settings (key,value) VALUES (?,?)
                ON CONFLICT(key) DO UPDATE SET value=excluded.value''', (key, value))
    return user_id


def get_user_profile(connection, user_id):
    """Read a profile with independent focus, series, club and bundle favorite sets."""
    user = _require_user(connection, user_id)
    directions = connection.execute('''SELECT d.key FROM user_directions u
        JOIN directions d ON d.id=u.direction_id WHERE u.user_id=?''', (user_id,)).fetchall()
    favorites = connection.execute('SELECT kind,target_id FROM favorites WHERE user_id=?',
                                   (user_id,)).fetchall()
    bundles = connection.execute('''SELECT b.key FROM favorites f JOIN bundles b ON b.id=f.target_id
        WHERE f.user_id=? AND f.kind='bundle' ''', (user_id,)).fetchall()
    series_ids, club_ids = set(), set()
    for row in favorites:
        if row['kind'] == 'series':
            series_ids.add(row['target_id'])
        elif row['kind'] == 'club':
            club_ids.add(row['target_id'])
    return models.UserProfile(user_id, user['display_name'], user['friend_code'],
                              {row['key'] for row in directions}, series_ids, club_ids,
                              {row['key'] for row in bundles})


def get_bundle_id(connection, bundle_key):
    """Resolve a stable bundle key to its database ID for favorite storage."""
    row = connection.execute('SELECT id FROM bundles WHERE key=?', (bundle_key,)).fetchone()
    if row is None:
        raise ValueError('Category was not found.')
    return row['id']


def _validate_favorite(connection, user_id, kind, target_id):
    """Check polymorphic favorite targets using fixed SQL, never interpolated table names."""
    _require_user(connection, user_id)
    queries = {'series': 'SELECT id FROM series WHERE id=?',
               'club': 'SELECT id FROM clubs WHERE id=?',
               'bundle': 'SELECT id FROM bundles WHERE id=?'}
    if kind not in queries or type(target_id) is not int or target_id <= 0:
        raise ValueError('Invalid favorite target.')
    if connection.execute(queries[kind], (target_id,)).fetchone() is None:
        raise ValueError('Favorite target was not found.')


def add_favorite(connection, user_id, kind, target_id, now=None):
    """Add one valid favorite without duplicating an existing selection."""
    _validate_favorite(connection, user_id, kind, target_id)
    with connection:
        connection.execute('''INSERT INTO favorites (user_id,kind,target_id,created_at)
            VALUES (?,?,?,?) ON CONFLICT(user_id,kind,target_id) DO NOTHING''',
            (user_id, kind, target_id, to_db_text(config.local_now(now))))


def remove_favorite(connection, user_id, kind, target_id):
    """Remove only the selected user's favorite; repeating removal is harmless."""
    _validate_favorite(connection, user_id, kind, target_id)
    with connection:
        connection.execute('DELETE FROM favorites WHERE user_id=? AND kind=? AND target_id=?',
                           (user_id, kind, target_id))


def get_user_interactions_df(connection, user_id):
    """Return the user's interaction state keyed by interaction ID."""
    return pd.read_sql('SELECT * FROM interactions WHERE user_id=?', connection,
                       index_col=['id'], params=(user_id,))


def get_interaction(connection, user_id, event_id):
    """Return one interaction dictionary, or None for an untouched occurrence."""
    row = connection.execute('SELECT * FROM interactions WHERE user_id=? AND event_id=?',
                             (user_id, event_id)).fetchone()
    return dict(row) if row is not None else None


def _validate_transition(event, previous, action, now):
    """Enforce the complete state and time rules in SPEC section 6.2 before any mutation."""
    status = previous['status'] if previous else None
    if status not in config.INTERACTION_TRANSITIONS[action]:
        raise ValueError('This action is not available in the current event state.')
    if action in ('confirm', 'cancel') and event.start <= now:
        raise ValueError('This event has already started.')
    if action == 'confirm' and event.status in config.HIDDEN_STATUSES:
        raise ValueError('This event is full or closed.')
    if action in ('attended', 'not_attended') and event.end >= now:
        raise ValueError('Attendance can be recorded only after the event has ended.')


def validate_interaction_input(user_id, event_id, action, rating=None):
    """Validate HTTP-compatible identifiers and action values before either storage path."""
    for value in (user_id, event_id):
        if type(value) is not int or not 1 <= value <= config.API_MAX_ID:
            raise ValueError('User ID and event ID must be positive integers.')
    if not isinstance(action, str) or action not in config.INTERACTION_TRANSITIONS:
        raise ValueError('Unknown interaction action.')
    if action == 'rate':
        if type(rating) is not int or not config.RATING_MIN <= rating <= config.RATING_MAX:
            raise ValueError('Rating must be an integer from 1 to 5.')
    elif rating is not None:
        raise ValueError('Use the rate action to save a rating.')


def save_interaction(connection, user_id, event_id, action, rating=None, now=None, is_demo=False):
    """Apply one validated state transition and return the saved interaction.

    :param connection: open SQLite connection
    :param user_id: owner of the interaction
    :param event_id: dated occurrence, never a complete recurring series
    :param action: confirm, cancel, attended, not_attended or rate
    :param rating: integer 1–5 only for rate
    :param now: injected naive Zurich clock
    :param is_demo: mark a newly created local demo row; never relabel existing genuine history
    :return: interaction dictionary; rejected actions leave storage unchanged
    """
    now = config.local_now(now)
    validate_interaction_input(user_id, event_id, action, rating)
    _require_user(connection, user_id)
    row = get_event_row(connection, event_id)
    if row is None:
        raise ValueError('Event was not found.')
    event = models.event_from_row(row)
    with connection:
        previous = get_interaction(connection, user_id, event_id)
        _validate_transition(event, previous, action, now)
        _write_interaction(connection, user_id, event_id, action, rating, previous, now)
        if previous is None and is_demo:
            connection.execute('UPDATE interactions SET is_demo=1 WHERE user_id=? AND event_id=?',
                               (user_id, event_id))
        if action == 'rate' and previous['rating'] != rating:
            _advance_rating_revision(connection)
    return get_interaction(connection, user_id, event_id)


def _write_interaction(connection, user_id, event_id, action, rating, previous, now):
    """Write a validated transition inside save_interaction's transaction."""
    stamp = to_db_text(now)
    confirmed = stamp if action == 'confirm' else previous['confirmed_at']
    answered = previous['answered_at'] if previous else None
    if action in ('attended', 'not_attended'):
        answered = stamp
    status = config.INTERACTION_TARGETS[action]
    connection.execute('''INSERT INTO interactions
        (user_id,event_id,status,rating,confirmed_at,answered_at) VALUES (?,?,?,?,?,?)
        ON CONFLICT(user_id,event_id) DO UPDATE SET status=excluded.status,rating=excluded.rating,
        confirmed_at=excluded.confirmed_at,answered_at=excluded.answered_at''',
        (user_id, event_id, status, rating, confirmed, answered))


def _advance_rating_revision(connection):
    """Invalidate a trained model after an effective rating change, in the same transaction."""
    # A corrected rating leaves COUNT(rating) unchanged; a revision covers that case (SPEC 6.2).
    connection.execute('''INSERT INTO app_settings (key,value) VALUES (?,?)
        ON CONFLICT(key) DO UPDATE SET value=CAST(CAST(value AS INTEGER) + 1 AS TEXT)''',
        ('ratings_revision', '1'))


def get_rating_cache_key(connection):
    """Return count and revision, so new or corrected ratings each invalidate the model once."""
    row = connection.execute('''SELECT COUNT(*) AS n FROM interactions
        WHERE status='attended' AND rating IS NOT NULL''').fetchone()
    return row['n'], int(get_setting(connection, 'ratings_revision', '0'))


def get_pending_feedback(connection, user_id, now=None):
    """Return ended confirmations and unrated attendance, oldest first.

    :param connection: open SQLite connection
    :param user_id: profile whose feedback is requested
    :param now: injected Zurich clock; an event ending exactly now is not yet pending
    :return: DataFrame indexed by interaction ID, including event ID, title and status
    """
    query = '''SELECT i.id,i.event_id,i.user_id,i.status,i.rating,i.is_demo,
        e.start_time,e.end_time,s.title FROM interactions i
        JOIN events e ON e.id=i.event_id JOIN series s ON s.id=e.series_id
        WHERE i.user_id=? AND e.end_time<? AND
        (i.status='confirmed' OR (i.status='attended' AND i.rating IS NULL))
        ORDER BY e.end_time,e.id'''
    return pd.read_sql(query, connection, index_col=['id'],
                       params=(user_id, to_db_text(config.local_now(now))))


def get_user_bundle_averages(connection, user_id, now=None):
    """Return averages from available attended ratings before now, excluding no-shows."""
    stamp = to_db_text(config.local_now(now))
    rows = connection.execute('''SELECT b.key,AVG(i.rating) AS average FROM interactions i
        JOIN events e ON e.id=i.event_id JOIN series s ON s.id=e.series_id
        JOIN bundles b ON b.id=s.bundle_id
        WHERE i.user_id=? AND i.status='attended' AND i.rating IS NOT NULL
        AND e.end_time<? AND (i.answered_at IS NULL OR i.answered_at<=?)
        GROUP BY b.key''', (user_id, stamp, stamp)).fetchall()
    return {row['key']: row['average'] for row in rows}


def get_training_interactions_df(connection, now=None):
    """Read only available attended ratings and their public occurrence fields.

    :param connection: open SQLite connection
    :param now: injected cutoff for ended events and available attendance answers
    :return: DataFrame in user/start order, indexed by interaction ID
    """
    stamp = to_db_text(config.local_now(now))
    query = '''SELECT i.id,i.user_id,i.event_id,i.rating,i.is_demo,u.is_synthetic,
        e.series_id,e.start_time,e.end_time,e.end_is_estimated,e.status,
        s.source,s.title,s.description,s.organizer,s.event_type,s.sport,s.level,
        s.location,s.location_type,s.source_url,s.registration_url,s.price_rappen,
        s.members_only,s.is_recurring,s.club_id,c.name AS club_name,c.club_category,
        b.key AS bundle_key,b.name AS bundle_name,d.key AS direction_key
        FROM interactions i JOIN users u ON u.id=i.user_id
        JOIN events e ON e.id=i.event_id JOIN series s ON s.id=e.series_id
        JOIN bundles b ON b.id=s.bundle_id JOIN directions d ON d.id=b.direction_id
        LEFT JOIN clubs c ON c.id=s.club_id
        WHERE i.status='attended' AND i.rating IS NOT NULL AND e.end_time<?
        AND (i.answered_at IS NULL OR i.answered_at<=?)
        ORDER BY i.user_id,e.start_time,i.id'''
    return pd.read_sql(query, connection, index_col=['id'], params=(stamp, stamp))


def get_training_summary(connection, now=None):
    """Count eligible synthetic, local demo and genuine ratings using the training query."""
    frame = get_training_interactions_df(connection, now)
    synthetic = frame['is_synthetic'] == 1
    demo = (frame['is_synthetic'] == 0) & (frame['is_demo'] == 1)
    yours = (frame['is_synthetic'] == 0) & (frame['is_demo'] == 0)
    return {'Synthetic': int(synthetic.sum()), 'Demo': int(demo.sum()),
            'Yours': int(yours.sum()), 'Total': len(frame),
            'Positive': int((frame['rating'] >= config.LABEL_MIN_STARS).sum())}


def clear_demo_history(connection, user_id):
    """Remove only the local user's opted-in demo interactions and invalidate learned ratings."""
    user = _require_user(connection, user_id)
    if user['is_synthetic']:
        raise ValueError('Demo history belongs to a local user, not a synthetic profile.')
    with connection:
        rated = connection.execute('''SELECT COUNT(*) AS n FROM interactions
            WHERE user_id=? AND is_demo=1 AND rating IS NOT NULL''', (user_id,)).fetchone()['n']
        removed = connection.execute('DELETE FROM interactions WHERE user_id=? AND is_demo=1',
                                     (user_id,)).rowcount
        if rated:
            _advance_rating_revision(connection)
    return removed


def get_synthetic_users_df(connection):
    """Read generated profiles in stable creation order for deterministic demo generation."""
    return pd.read_sql('SELECT * FROM users WHERE is_synthetic=1 ORDER BY id', connection,
                       index_col=['id'])


def get_favorite_target_ids(connection):
    """List existing series and clubs in stable order for generated favorite choices."""
    series = connection.execute('SELECT id FROM series ORDER BY id').fetchall()
    clubs = connection.execute('SELECT id FROM clubs ORDER BY id').fetchall()
    return {'series': [row['id'] for row in series], 'club': [row['id'] for row in clubs]}


def remove_incomplete_synthetic_seed(connection):
    """Remove an interrupted seed only, preserving every local profile and interaction."""
    if get_setting(connection, 'synthetic_setup_done') == '1':
        raise ValueError('A complete synthetic dataset must not be removed during startup.')
    with connection:
        connection.execute('''DELETE FROM invitations WHERE sender_id IN
            (SELECT id FROM users WHERE is_synthetic=1) OR recipient_id IN
            (SELECT id FROM users WHERE is_synthetic=1)''')
        connection.execute('''DELETE FROM friendships WHERE user_id IN
            (SELECT id FROM users WHERE is_synthetic=1) OR friend_id IN
            (SELECT id FROM users WHERE is_synthetic=1)''')
        connection.execute('''DELETE FROM interactions WHERE user_id IN
            (SELECT id FROM users WHERE is_synthetic=1)''')
        connection.execute('''DELETE FROM favorites WHERE user_id IN
            (SELECT id FROM users WHERE is_synthetic=1)''')
        connection.execute('''DELETE FROM user_directions WHERE user_id IN
            (SELECT id FROM users WHERE is_synthetic=1)''')
        connection.execute('DELETE FROM users WHERE is_synthetic=1')


def reset_database(connection):
    """Reset generated/local database state only when explicitly regenerating the demo.

    Private calendar/source files are outside SQLite and are never touched here. Startup upgrades
    do not call this function; the command-line demo regeneration is an explicit reset operation.
    """
    with connection:
        connection.executescript('''
            DROP TABLE IF EXISTS import_log;
            DROP TABLE IF EXISTS app_settings;
            DROP TABLE IF EXISTS invitations;
            DROP TABLE IF EXISTS friendships;
            DROP TABLE IF EXISTS interactions;
            DROP TABLE IF EXISTS favorites;
            DROP TABLE IF EXISTS user_directions;
            DROP TABLE IF EXISTS users;
            DROP TABLE IF EXISTS events;
            DROP TABLE IF EXISTS series;
            DROP TABLE IF EXISTS clubs;
            DROP TABLE IF EXISTS bundles;
            DROP TABLE IF EXISTS directions;
        ''')
    init_db(connection)
